84:export const isVersion = (v) => parseVersion(v) !== null;
87:export const isDeclaredVersion = (v) => isVersion(v) && v !== 0;
92:export const isLegacyVersion = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0;
