// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
// engine tree vendors wholesale on every converge; a pack's directory ships only
// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`. So a
// canon commit that edits `packs/<id>/` without moving that number reaches no member —
// the fleet keeps the old bytes while the canon believes the change shipped (#939
// froze seven repos for five days that way), and two changes landing under ONE
// number strand whichever members converged between them (#1482).
//
// So the number is not the pull request's to move. It is read off `main` after the
// fact: this module walks a pack's history on the base branch, finds the commit that
// last moved its version, and asks whether any SHIPPING byte under `packs/<id>/` has
// changed since. Every such pack takes the next version cut today, in one commit,
// from one writer — which is what makes a collision impossible rather than merely
// checked for. The same walk, read the other way round, says which pull requests each
// version carried, which is what the version-history rows are made of.
//
// Both readers are here so the two tasks that need them — the bump on every push to
// main, and the weekly history — cannot disagree about what a bump or a shipping file
// is. Pure over a `git` runner the caller hands in, so the tests drive them against a
// scratch repository and the workers against the real one.

import { LOCAL_PACKS_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';
// A namespace import: the pack and engine lanes deliver on separate cadences, and a
// member whose engine predates the constant must still load this pack.
import * as conventions from '../../engine/pack_loader/pack-conventions.mjs';

const { PROVENANCE_DIR } = conventions;
const VERSIONS_FILE = conventions.VERSIONS_FILE ?? 'VERSIONS.md';
import {
  VERSION_SOURCE, versionFromLiteral, compareVersions, versionsEqual, nextVersion, versionAbove,
} from '../../engine/version.mjs';

// The pack-shelf root the engine reads a canon's packs from, and the one tree this
// module ever looks at. A repo's OWN packs are neither versioned nor vendored, so
// nothing about them is a delivery question.
export const SHELF = 'packs';
const LOCAL_ROOT = `${LOCAL_PACKS_SUBDIR}/`;

// Each pack's version-history record, under its `provenance/` with the rest of what is
// read by maintenance and never by a session or a member.
export const VERSIONS_FILENAME = VERSIONS_FILE;
export const versionsPath = (id) => `${SHELF}/${id}/${PROVENANCE_DIR}/${VERSIONS_FILENAME}`;

// The task that writes bump commits, named where the commit is stamped and where the
// history reads the stamp back: a bump commit moves only version numbers, so it is
// never something a version "shipped".
export const BUMP_TASK = 'claudinite-canon-curation/pack-version-bump';

// Does this path ride a pack's directory copy to a member? A pack's tests sit beside
// the files they cover and its pack-root `provenance/` is its decision log, and neither
// reaches a member (compute-vendor-set drops `*.test.mjs` and that folder), so nobody
// is waiting on them: a backfilled entry, or a version-record row, must never itself
// demand another version.
export function isShippingFile(path) {
  if (path.startsWith(LOCAL_ROOT)) return false;
  if (path.endsWith('.test.mjs') || new RegExp(`^${SHELF}/[^/]+/${PROVENANCE_DIR}/`).test(path)) return false;
  return /^packs\/[^/]+\//.test(path);
}

// The pack id a shipping path belongs to, or null.
export function packOf(path) {
  const m = /^packs\/([^/]+)\//.exec(path);
  return m ? m[1] : null;
}

// The `version:` a pack manifest declares, or null when it declares none (a manifest
// absent on one side of the history, or one the schema check owns). The preceding
// character class is what keeps `minEngineVersion:` out of it.
const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
export function declaredPackVersion(text) {
  const m = PACK_VERSION_RE.exec(text ?? '');
  return m ? versionFromLiteral(m[1]) : null;
}

// The manifest text with its `version:` literal replaced — and nothing else moved,
// so the commit that bumps a pack is a one-line diff on a file people edit by hand.
export function withPackVersion(text, version) {
  return text.replace(PACK_VERSION_RE, (whole, old) => whole.replace(old, String(version)));
}

// THE ENGINE VERSION — the value that says which engine release a repo is running
// (docs/versioned-updates/DESIGN.md §2). The engine root vendors wholesale, so this
// module ships into every mount with the rest of the engine, and a member's stamp
// records the value it received (vendoring/apply-vendor-set.mjs). That pair is what
// makes "installed version → target version" answerable on the member side: which
// engine migrations still apply, and whether a pack's minimum is satisfied.
//
// DATE-ANCHORED, `<day>.<n>` — the shape, the ordering and why the corpus versions
// this way rather than in semver are stated below the constant. Every comparison made
// of this value is "installed < target" over a total order, so the format buys one
// thing over the plain counter it replaced: the version says when it was cut, without
// a second lookup.
//
// ADVANCED BY RELEASE, never by an ordinary change: a release is a snapshot that has
// passed the live canary rehearsal once (DESIGN §2.1), and the bump is what declares
// that happened. An engine migration is written against the version it lands in — it
// applies to repos below that value.
export const ENGINE_VERSION = '60902.1';

// THE VERSION FORMAT — how every engine and pack version in the corpus is written,
// read and ordered. The helpers below are imported by every side that creates a
// version (each `packs/*/pack.mjs`), stamps one (the update
// flows), compares two (the update
// planners, the dashboard, the fleet roster) or scrapes one out of source text over
// the API. They live beside the constant rather than in a module of their own so the
// engine surface a member's mount must carry for any of it is one file.
//
// THE SHAPE IS `<day>.<n>` — `60820.1`, displayed with a leading `v`. The day part
// is `(year - 2020) * 10000 + month * 100 + day`, so 2026-08-20 is 60820; the second
// part is the running number of versions cut on that day, starting at 1. It is a
// STRING and never a float: `60820.10` and `60820.1` are different versions and the
// same number.
//
// Anchoring the year on 2020 rather than taking its last digit is what keeps the day
// part monotonic past 2029 — 2030 reads 100101, above every 2029 value, where a
// last-digit year would wrap to 0 and sort a decade of releases underneath.
//
// WHY DATE-ANCHORED AT ALL. Every comparison the update flows make is still
// "installed < target" over a total order — nothing here needs semver's three
// components. What the plain counter could not do is say WHEN: a member stamped at 6
// against a canon at 13 is behind by an unknown amount of time, and the fleet
// surfaces that as a number a reader has to go and date by hand.
//
// LEGACY TOLERANCE (#1912). Versions were plain positive integers until 2026-08-20,
// so a legacy integer parses here as `<n>.0` - below every date-anchored version,
// which is exactly where a member that has not re-stamped belongs. Dependency-free,
// like the manifest spec it serves.
//
// It did not come out with the declaration-shape tolerances (#1640), and the reason
// is in this repo rather than in the fleet: the canon's own migration records
// declare an integer `version:`, `recordVersion` reads that field through
// `versionFromLiteral`, and an unpriceable record silently changes which records
// `migrationActive` selects. #1912 takes those records first.

// The day part of a Date, in UTC. Callers that have a `YYYY-MM-DD` string already
// (the corpus passes `today` around in that form) can hand it straight over.
export function versionDay(when = new Date()) {
  const d = typeof when === 'string' ? new Date(`${when.slice(0, 10)}T00:00:00Z`) : when;
  if (Number.isNaN(d.getTime())) return null;
  return (d.getUTCFullYear() - 2020) * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();

import { finding } from '../../../engine/checks/helpers/findings.mjs';
// A NAMESPACE import, and the guard below, because the two lanes deliver on
// separate cycles: a member takes this pack version nightly and the engine only
// on a release, so a window exists where this file sits beside an engine with no
// `unplacedSpecKeys` to export. A named import of an absent export is a link-time
// SyntaxError, which the loader records as a fault, which fails the self-test,
// which parks the converge — #1400's own wedge, from the other lane.
import * as patternRules from '../../../engine/checks/helpers/pattern-rules.mjs';

// A declared check's keys ARE its vocabulary: write `scanFile` for `scanFiles`
// and the assertion the key carried is simply not there, asserting nothing and
// reading green forever. The load used to throw on such a key; it now drops it,
// because a key it cannot place is equally a key a NEWER engine knows and
// refusing it wedges the member holding an older one (#1400, pattern-rules.mjs).
// This rule is where the typo half is caught instead — advisory by default,
// because in a member either reading is possible, and overridden to blocking in
// the canon, where engine and declarations ship from one commit so a key the
// engine cannot place can only be a typo.
//
// Coded rather than declared: the assertion is "every key, at every level, is in
// its own container's allowlist", which is a recursive descent against a
// per-container vocabulary the declaration language cannot express — and the
// vocabulary itself is the engine's, read from it here rather than restated.
const DECLARED = /(^|\/)declared-checks\.json$/;

