// missing credential, a failed signal read, a throwing term. An error FAILS OPEN:
// the item is created and the executor, which holds the credentials, decides at
// pick. It is REQUIRED wherever a task is asked — a fixture with no seam and a
// task to ask is a fixture that has not said what the task answers.
export async function planSchedulerRun({
  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
  stateOf = () => null, evaluate = null,
  progressAt = () => null, resolutionOf = () => null, doneAfter = () => null,
}) {
  const nowMs = ms(now);
  const ops = [];
  const asked = [];
  // REPO SHAPE IS NOT A PRECONDITION (docs/PRINCIPLES.md). "This repo ships the store pipeline", "this repo is a canon
  // home with a fleet token" are facts adoption settled, not questions worth
  // re-asking every tick — so a repo that carries a pack but not one task's
  // subject names that task in `taskScheduler.disabledTasks` and it is never
  // asked. Read here rather than at pick, because the cheapest run is the one
  // that files no item at all.
  const disabled = new Set(schedule?.disabledTasks ?? []);
  const closedByThisRun = new Set();

  // ---- the repair phase, FIRST (repair.mjs) --------------------------------
  // Recovery runs before anything else this run does, because what it frees is
  // what the jobs below read: a park it closes releases the task's lane for job 1,
  // and an item it returns to the queue is counted by the drain gate that ends the
  // run. Its threaded effects are applied to `items` in place, so every job after
  // this line - and every cadence term the ask evaluates - judges this run's world
  // rather than the listing it started from.
  const repair = planRepair({ items, tasks, now, progressAt, resolutionOf, doneAfter,
    isRequest: (n) => requests.some((r) => r.number === n), stateOf });
  ops.push(...repair.ops);
  for (const n of repair.closed) closedByThisRun.add(n);

  // ---- the orphan reap ----------------------------------------------------
  // A blocked standing item whose `<pack>/<task>` is not declared at HEAD can
  // never execute — job 1 matches its family title-exact on the declared id, so a
  // legacy pack spelling is invisible to it, and job 2 would otherwise ready the
  // item at its Not-before and hand an executor a task path that is not on disk.
  // Guarded on a non-empty task list so an unreadable declaration reaps nothing,
  // and scoped to BLOCKED so nothing in flight is touched — a ready orphan is
  // picked within the tick and parks for a human, which is visible rather than
  // silent. Items waiting on a blocker are untouched: they are somebody's
  // dependency, not a schedule's.
  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
  for (const item of items) {
    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
    const parsed = parseWorkItemTitle(item.title);
    if (!parsed || parsed.qualifier !== null) continue;
    const key = `${parsed.pack}/${parsed.task}`;
    if (parseWorkItemBody(item.body).blockedBy.length) continue;
    if (byId.has(key) && !disabled.has(key)) continue;
    closedByThisRun.add(item.number);
    ops.push({
      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
      reason: disabled.has(key)
        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
          + 'asked here. Remove it from that list to bring the task back.'
        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
          + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
    });
  }

  // ---- job 1: ask every task on the schedule; a yes files the item ----------
  const live = (i) => LIVE_STATUSES.some((s) => isStatus(i, s));
  for (const task of tasks) {
    // A task whose declaration says `trigger: 'request'` runs only from an item
    // somebody created (docs/PRINCIPLES.md): the schedule never asks it, and its items
    // keep their own titles.
    if (!isScheduledTask(task.decl)) continue;
    const key = `${task.pack}/${task.id}`;
    if (disabled.has(key)) continue;
    const title = workItemTitle({ pack: task.pack, task: task.id });
    // The family is title-EXACT, which is also what makes it STRUCTURALLY the
    // standing family (PRINCIPLES.md): this task is on the schedule and the title carries
    // no qualifier, so a fan-out target or a request — qualified, both of them — is
    // a different title and neither suppresses nor consumes an occurrence (PRINCIPLES.md).

// The `tidy-repo` pack was absorbed into `basics` (#1839). Its issue and PR sweeps
// were retired with the two per-object skills they applied; its comment pass, that
// pass's skill and the `improve-comments-scope` gate moved into the baseline.
//
// WHAT ONLY THIS RECORD CAN DO is converge the declaration. The rename map resolves
// the id at read time, so a member reads correctly whether or not this has run; what
// the record buys is the day the map can come out — and, before that, a declaration
// that says what is actually on the shelf rather than a pack directory nothing holds.
//
// NO `absorbedPackConfig`. That op nests an absorbed entry's parameters under the
// survivor's `config`, which is what a pack with parameters needs. `tidy-repo` asked
// no adoption question and read no config, so its entry is a bare id everywhere and
// the rename plus the duplicate-merge in `applyPackRenames` is the whole change.
//
// NO `appliesTo` GATE either. `renameDeclaredPacks` is an op every engine in the
// vendoring window already runs, so there is no capability to probe for — unlike the
// `barriers` absorption (#1681), whose nesting op was new in the same release.
//
// IT LIVES IN THIS PACK, not in the one that absorbed the content, for the same
// reason that absorption's record does: what it rewrites is the member's declaration,
// which is this pack's surface. A record's version must also sit at or below its own
// pack's, and a pending record above `basics`'s number would ride into a FRESH
// INSTALL — `installPacks` forces the stamp to each manifest's current version and
// fetches whatever still applies above it, and an install must carry no records at
// all (engine-tests/install.test.mjs).
export default {
  id: 'tidy-repo-absorbed',
  landed: '2026-09-06',
  // The version is cut on main after the merge (#1726), so a record cannot name it
  // exactly: this is the next number the bump would cut for the pack at 60906.10 —
  // above every member's installed version, so the gap holds the record, and never
  // above the number cut, so a converged member does not re-apply it. RE-CHECK IT
  // AGAINST `pack.mjs` ON EVERY REBASE: main cuts versions while a branch waits, and
  // a record that falls at or below the installed version is silently already done.
  version: '60906.11',
  summary: 'the tidy-repo pack is absorbed into basics (#1839) — its issue and PR sweeps are retired and the declared entry is renamed onto the pack that now carries the comment pass',

  renameDeclaredPacks: true,
};

