// `Claudinite-Task:` trailer. That is the whole silence gate — a movement-gated
// task cannot be woken by another task's output, and no operator or marker says
// so in the declaration.

const commitsOf = (s) => s?.commits ?? {};
const touchedPaths = (s) => commitsOf(s).touchedPaths ?? [];

// THE RUN HISTORY: this task's own unqualified work items, newest first, other
// than the item under evaluation — what the `runs` collector reads off the issue
// list over a fixed horizon. Each `{ number, createdAt, closedAt, state, status,
// park, outcome }`. The engine keeps no other memory of a task: the queue IS the
// record, which is why a renamed task simply reads as never having run.
const runsOf = (s) => s?.runs?.list ?? [];
const newestRun = (s) => runsOf(s)[0] ?? null;
const ms = (t) => (t == null ? null : new Date(t).getTime());

// A person's wake stands in for the cadence: the cadence terms hold on a woken
// item, and everything else the task requires still applies, so a force that
// finds no work still says so.
const wokenReason = (item) => (item?.woken === true
  ? { holds: true, reason: `#${item.number ?? '?'} was woken by hand — the wake stands in for the cadence` }
    // exists for a tampered or forged item, whose path names some OTHER task — that
    // parks. But an item open across a pack rename hits it too: only the title's id is
    // canonicalized (`parseWorkItemTitle`), so the body keeps naming the pre-rename
    // directory forever, and parking it strands the item AND holds the task's lane,
    // since nothing rewrites an item body. When the path resolves to this very task —
    // `taskIdFromPath` canonicalizes too — the item is merely stale, which is the
    // `!task` branch's verdict: close it obsolete and let the generator file a fresh
    // occurrence at today's path.
    const named = taskIdFromPath(taskPath);
    if (named && `${named.pack}/${named.task}` === id) {
      await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_REJECTED, 'not_planned',
        `This item names \`${id}\` at \`${taskPath}\`, where it no longer lives — the pack was renamed since the item `
        + `was filed, and the task is at \`${task.taskPath}\` now. An item's stored path is never rewritten, so this one `
        + 'can never run. Closing obsolete; the scheduler files a fresh occurrence at the current path.', 'task-gone');
      return 'obsolete';
    }
    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
    return 'needs-human';
