// The 2026-08-11 fleet-baseline conversion (#749): the sheepdog pack's manual lever
// over the fleet stopped being a standalone WORKFLOW (a managed copy in the enforcer's
// own .github/, the one file the nightly converge could never push — #649) and became
// an ordinary `manual`-frequency TASK (packs/sheepdog/tasks/fleet-baseline/) riding
// the vendored scheduler: Actions → Claudinite scheduler → Run workflow →
// `overrides: FORCE_TASKS=fleet-baseline`.
//
// Canon-side the conversion is complete — the stub the old record materialized
// (packs/sheepdog/stubs/workflows/fleet-baseline.yml) is deleted, which makes the
// 2026-08-05 sheepdog-fleet-baseline record's materialization a permanent no-op (a
// missing template is a skip, never a clobber; see applyMaterializations). What
// remains member-side is the COPY that record installed: an enforcer's own
// .github/workflows/fleet-baseline.yml, now orphaned — its `run:` step points at a
// mount path the vendor refresh no longer carries, so left in place it is a button
// that fails when pressed. Removing a workflow file needs the `workflows` permission
// the Action token does not hold, so the removal rode an agent stage over MCP — the
// same lane that landed the file (#649), run in reverse.
//
// THAT WORK IS DONE. The enforcer's orphaned copy is gone, and this record's
// `agentic:` note went with the field itself when #768 Phase 5 retired it. The record
// stays as the dated account of the conversion, and `legacyPresent` still answers the
// tolerance question for any repo that somehow still carries the file.
// BOTH settings-file names (#1252). This record is gated on a PACK's version, so it
// can still be in a member's gap long after that member renamed its settings file —
// and a read that only knew the name in use when this landed would find nothing and
// silently never apply.
const DECLARATIONS = ['.claudinite-settings.json', '.claudinite-checks.json'];
const readDeclaration = async (read) => {
  for (const name of DECLARATIONS) {
    const raw = await read(name);
    if (raw != null) return raw;
  }
  return null;
};
// Matched through the rename map: the pack was called `sheepdog` when this record
// landed, and an enforcer's declaration converges onto the current id on its own
// schedule.
const PACK = 'claudinite-fleet-sheepdog';

export default {
  id: 'fleet-baseline-task',
  landed: '2026-08-11',
  version: 1,
  summary: 'fleet-baseline converted from a standalone workflow to a manual-frequency sheepdog task; the enforcer\'s .github/workflows/fleet-baseline.yml copy is retired',

  // Same gate as the record that installed the file: does this repo declare the
  // sheepdog pack. An unreadable declaration means "not an enforcer as far as this
  // record can tell" — skip, never guess.
  appliesTo: async (read) => {
    const text = await readDeclaration(read);
    if (!text) return false;
    let cfg;
    try { cfg = JSON.parse(text); } catch { return false; }
    return (Array.isArray(cfg?.packs) ? cfg.packs : [])
      .some((e) => (typeof e === 'string' ? e : e?.id) === PACK);
  },

  legacyPresent: async (exists) => exists('.github/workflows/fleet-baseline.yml'),
};
test('every record folder is <landed>-<slug>/migration.mjs, prefix matching its landed date', async () => {
  const migs = await loadMigrations();
  assert.equal(migs.length, migrationDirs().length);
  for (const m of migs) {
    assert.match(recordName(m.dir), /^\d{4}-\d{2}-\d{2}-/, `dated folder: ${m.dir}`);
    assert.equal(recordName(m.dir).slice(0, 10), m.landed, `folder prefix = landed for ${m.id} — vendoring and tolerance window off the prefix`);
  }
});

// A workflow materialization can only be written by a caller that can get it delivered.
// Writing one into a tree an Action-token push is about to carry does not deliver a
// workflow — it rejects the whole ref and fails the converge with everything riding it.

test('applyMaterializations: a workflow dest is skipped unless the caller announced it can withhold', async () => {
  const m = M({ materialize: [
    { template: 'tpl/wf.yml', dest: '.github/workflows/fleet-baseline.yml' },
    { template: 'tpl/act.yml', dest: '.github/actions/thing/action.yml' },
  ] });
  const written = new Map();
  const io = (env) => ({
    readTemplate: async (p) => `content of ${p}`,
    read: async (p) => written.get(p) ?? null,
    write: async (p, c) => { written.set(p, c); },
    env,
  });

  // An incapable caller — an older vendored worker, a hand-run apply, CI.
  const skipped = await applyMaterializations(m, io({}));
  assert.deepEqual(skipped, [
    'SKIPPED .github/workflows/fleet-baseline.yml (workflow file; this caller cannot deliver one)',
    '.github/actions/thing/action.yml <- tpl/act.yml',
  ]);
  // The workflow was NOT written; the ordinary .github/ file was. Only workflow files are
  // special — an action, a template, a CODEOWNERS all push fine with the Action token.
  assert.equal(written.has('.github/workflows/fleet-baseline.yml'), false);
  assert.equal(written.get('.github/actions/thing/action.yml'), 'content of tpl/act.yml');
  // And it SAYS it skipped: a silent skip reads as "already current", and the file would
  // then never arrive at all.

  // The capable caller writes it, and the withhold path downstream keeps it out of the push.
  const applied = await applyMaterializations(m, io({ CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' }));
  assert.deepEqual(applied, ['.github/workflows/fleet-baseline.yml <- tpl/wf.yml']);
  assert.equal(written.get('.github/workflows/fleet-baseline.yml'), 'content of tpl/wf.yml');
});

test('callerCanDeliverWorkflows: only the exact announcement counts', () => {
  assert.equal(callerCanDeliverWorkflows({ CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' }), true);
  for (const env of [{}, { CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '' }, { CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: 'true' }, { CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '0' }]) {
    assert.equal(callerCanDeliverWorkflows(env), false, JSON.stringify(env));
  }
});

test('sheepdog-fleet-baseline migration: gated on declaring the pack, and on nothing else', async () => {
  const m = (await loadMigrations()).find((x) => x.id === 'sheepdog-fleet-baseline');
  assert.ok(m, 'discovered');
  const read = (decl) => async (p) => (p === '.claudinite-settings.json' ? decl : null);

  // Both declaration forms, since both are legal.
  assert.equal(await m.appliesTo(read(JSON.stringify({ packs: [{ id: 'claudinite-fleet-sheepdog', config: {} }] }))), true); // @real-entity the record under test names this pack; that is its content
  assert.equal(await m.appliesTo(read(JSON.stringify({ packs: ['claudinite-fleet-sheepdog'] }))), true); // @real-entity the record under test names this pack; that is its content
  // Not under the spelling an enforcer's declaration carried when the record landed:
  // that tolerance came out with the rest of the 2026-08-19 renames (#1641), and an
  // enforcer still declaring it has no pack for this record to apply to.
  assert.equal(await m.appliesTo(read(JSON.stringify({ packs: ['sheepdog'] }))), false);
  assert.equal(await m.appliesTo(read(JSON.stringify({ packs: ['acme-pack'] }))), false);
  assert.equal(await m.appliesTo(read('not json')), false);
  assert.equal(await m.appliesTo(read(null)), false);   // canon itself

  assert.equal(await m.legacyPresent(() => false, async () => null), false);
});

