1	// Scope-blind mechanism: hold a newly-added check to its grace window, apply the
2	// project's on_fail overrides and acceptances, order blocking-first, print each
3	// finding, and print the one-line summary.
4	// Returns the blocking count so a runner's exit code is `blocking ? 1 : 0`.
5	// `scopeLabel` only names the run in the summary line (e.g. "world" / "work") —
6	// this file carries no scope logic of its own.
7	import { applyConfig, applyGrace, render } from './helpers/findings.mjs';
8	
9	export function reportFindings(findings, config, { scopeLabel, mode, baseRef, now = new Date() }) {
10	  const resolved = applyConfig(applyGrace(findings, { now }), config)
11	    .sort((a, b) => (a.on_fail === b.on_fail ? 0 : a.on_fail === 'block' ? -1 : 1));
12	  for (const f of resolved) console.log(`${render(f)}\n`);
13	  const blocking = resolved.filter((f) => f.on_fail === 'block').length;
14	  const advisory = resolved.length - blocking;
15	  if (resolved.length) {
16	    console.log(`${blocking} blocking, ${advisory} advisory (${scopeLabel} scope: ${mode}${baseRef ? ` vs ${baseRef}` : ''}).`);
17	  }
18	  return blocking;
19	}

