 * invoked through `runRule`, the same dispatch seam the runner uses, so a
 * work-scoped rule gets its fluent surface here exactly as it does in a run.
 * A flagged case's `at` lists every expected finding in engine
 * order; each expectation may pin `file` (exact), `line` (exact — a finding
 * with no line anchor carries the explicit `line: null`), `severity` (exact),
 * and `what` / `fix` (regexes). Keys an expectation omits are not judged.
 */
export function ruleTester(rule, { clean = {}, flagged = {} }) {
  const runCase = (c) => {
    const root = makeRepo({
      base: c.base ?? {}, changed: c.files ?? {}, uncommitted: c.uncommitted ?? {},
      ...(c.commitMsg ? { commitMsg: c.commitMsg } : {}),
    });
    try {
      return runRule(rule, buildContext({ root, mode: c.mode ?? 'all' }));
    } finally { cleanup(root); }
  };
  for (const [name, c] of Object.entries(clean)) {
    test(`${rule.id}: ${name}`, () => {
      assert.deepEqual(runCase(c), []);
    });
  }
  for (const [name, c] of Object.entries(flagged)) {
    test(`${rule.id}: ${name}`, () => {
      const findings = runCase(c);
      assert.equal(findings.length, c.at.length,
        `expected ${c.at.length} finding(s), got ${findings.length}: ${JSON.stringify(findings, null, 2)}`);
      c.at.forEach((expected, i) => {
        const got = findings[i];
        if ('file' in expected) assert.equal(got.file, expected.file);
        if ('line' in expected) assert.equal(got.line, expected.line);
        if ('severity' in expected) assert.equal(got.severity, expected.severity);
        if ('what' in expected) assert.match(got.what, expected.what);
        if ('fix' in expected) assert.match(got.fix, expected.fix);
      });
    });
    /"match" is not a valid regex/,
  );
  assert.throws(
    () => patternRule({ ...meta('fx-bad-since'), since: '27th', scanFiles: /\.txt$/ }),
    /"since" is the date this check was added/,
  );
  assert.throws(
    () => patternRule({ id: 'fx-bad-severity', severity: 'fatal', failureMessage: 'm', scanFiles: /\.txt$/ }),
    /severity/,
  );
});
  try {
    assert.deepEqual(loadDeclaredChecks(join(dir, 'empty')), []);
    writeFileSync(join(dir, 'declared-checks.json'), JSON.stringify([
      { id: 'fx-declared-a', on_fail: 'advise', failureMessage: 'a', scanFiles: '/\\.txt$/', matchLines: [{ match: '/bad/', what: 'w', fix: 'f' }] },
      { id: 'fx-declared-b', on_fail: 'block', failureMessage: 'b', scanFiles: 'CLAUDE.md', maxLines: { limit: 1, what: '{lines}', fix: 'f' } },
    ]));
    const rules = loadDeclaredChecks(dir);
    assert.deepEqual(rules.map((r) => r.id), ['fx-declared-a', 'fx-declared-b']);
    assert.deepEqual(rules.map((r) => r.severity), ['advisory', 'blocking']);
    // Compiled once: a second read hands back the same rule objects, so the
    // registry and a test asking for the same declaration share one scan.
    { type: 'user', message: { content: [{ type: 'tool_result', tool_use_id: 't3', is_error: false, content: 'Blocked by fx-guard-denied: printed by the command itself' }] } },
  ]);
  const root = makeRepo({ changed: { 'a.txt': 'x\n' } });
  try {
    const findings = runRule(rule, buildContext({ root, mode: 'all', transcriptPath: session.path }));
    assert.deepEqual(findings.map((f) => [f.file, f.severity, f.what]), [
      ['(session) Bash call #1', 'advisory', 'sleep 5 (denied at the hook)'],
      ['(session) Bash call #2', 'advisory', 'sleep 6'],
      ['(session) Bash call #3', 'advisory', 'sleep 7'],
    ]);
    const c = await world(conflicted);
    assert.equal(c.status, 1);
    assert.match(c.stdout, /rule "reference-integrity" is set to "off" by the top-level "rules" and "advisory" by the "basics" pack entry/); // @real-entity the real check ids the catalog must carry, and the real closure the seed writes
  } finally { cleanup(unknown); cleanup(conflicted); }
});

test('severity override in config demotes a blocking rule to advisory', async () => {
  const root = makeRepo({
    changed: {
      'doc.md': '[gone](missing.md)\n',
      '.claudinite-settings.json': JSON.stringify({ packs: [A_CANON_PACK], rules: { 'reference-integrity': 'advisory' } }),
    },
  });
  try {
    assert.equal((await work(root)).status, 0);
  } finally { cleanup(root); }
});

